    reversed_values = values[:j+1] + values[j+1:i][::-1] + values[i:]
    if reversed_values == sorted(values):
        return f"{j+2} {i}"

    return "impossible"

def binary_search(lis, value):
    low, high = 0, len(lis)
    while low < high:
        mid = (low + high) // 2
        if lis[mid] < value:
            low = mid + 1
        else:
            high = mid
